import{_ as t,o as a,c as o,a4 as n}from"./chunks/framework.DCsBdTIw.js";const m=JSON.parse('{"title":"Dify","description":"Connect Dify to Tokeness through the OpenAI-API-compatible plugin or a custom model provider.","frontmatter":{"title":"Dify","description":"Connect Dify to Tokeness through the OpenAI-API-compatible plugin or a custom model provider."},"headers":[],"relativePath":"integrations/dify.md","filePath":"integrations/dify.md","lastUpdated":1784332800000}'),i={name:"integrations/dify.md"};function d(l,e,s,r,p,h){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="dify" tabindex="-1">Dify <a class="header-anchor" href="#dify" aria-label="Permalink to &quot;Dify&quot;">​</a></h1><p>Dify can connect to external models through model providers. To integrate Tokeness, use Dify&#39;s OpenAI-API-compatible plugin or OpenAI-compatible model provider, and fill in the Tokeness API endpoint, API key, and model name.</p><h2 id="connection-details" tabindex="-1">Connection Details <a class="header-anchor" href="#connection-details" aria-label="Permalink to &quot;Connection Details&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Provider</td><td>OpenAI-API-compatible</td></tr><tr><td>API Endpoint / Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>A key created in the Tokeness console</td></tr><tr><td>Model Name</td><td>The full model name from the Tokeness model catalog</td></tr></tbody></table><p>If your Dify version already has a built-in OpenAI Compatible provider, use it directly. If there is no built-in entry, install the OpenAI-API-compatible plugin from the Marketplace.</p><h2 id="_1-prepare-tokeness" tabindex="-1">1. Prepare Tokeness <a class="header-anchor" href="#_1-prepare-tokeness" aria-label="Permalink to &quot;1. Prepare Tokeness&quot;">​</a></h2><p>Prepare the following first:</p><ol><li>A dedicated API key for Dify.</li><li>A chat model name.</li><li>If you plan to use RAG, also prepare an embedding model name.</li><li>Available balance.</li></ol><p>Name the key something like:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dify-workspace</span></span></code></pre></div><p>Create separate keys for production and test environments.</p><h2 id="_2-install-or-open-the-model-provider" tabindex="-1">2. Install or Open the Model Provider <a class="header-anchor" href="#_2-install-or-open-the-model-provider" aria-label="Permalink to &quot;2. Install or Open the Model Provider&quot;">​</a></h2><p>In the Dify workspace, navigate to:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Settings -&gt; Model Provider</span></span></code></pre></div><p>If you see OpenAI-API-compatible or OpenAI Compatible, open its configuration directly.</p><p>If you do not see it:</p><ol><li>Open the Dify Marketplace.</li><li>Search for <code>OpenAI-API-compatible</code>.</li><li>Install the <code>langgenius/openai_api_compatible</code> plugin.</li><li>Return to the model provider settings page.</li></ol><h2 id="_3-add-a-tokeness-llm" tabindex="-1">3. Add a Tokeness LLM <a class="header-anchor" href="#_3-add-a-tokeness-llm" aria-label="Permalink to &quot;3. Add a Tokeness LLM&quot;">​</a></h2><p>Add a model under the OpenAI-API-compatible provider.</p><p>Fill in:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>API Endpoint: https://n.tokeness.io/v1</span></span>
<span class="line"><span>API Key: your Tokeness API key</span></span>
<span class="line"><span>Model Name: the model name copied from the Tokeness model catalog</span></span></code></pre></div><p>Select LLM or Chat Model as the model type. Fill in context length, max output, function calling, and multimodal capabilities according to the Tokeness model catalog and your own test results.</p><p>If Dify asks for a Completion mode, prefer Chat Completion for standard chat applications.</p><h2 id="_4-add-an-embedding-model" tabindex="-1">4. Add an Embedding Model <a class="header-anchor" href="#_4-add-an-embedding-model" aria-label="Permalink to &quot;4. Add an Embedding Model&quot;">​</a></h2><p>If your Dify application uses a knowledge base, you also need to add an embedding model.</p><p>Fill in the same way as the chat model:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>API Endpoint: https://n.tokeness.io/v1</span></span>
<span class="line"><span>API Key: your Tokeness API key</span></span>
<span class="line"><span>Model Name: the embedding model name copied from the Tokeness model catalog</span></span></code></pre></div><p>Notes:</p><ul><li>Chat models and embedding models are not the same thing.</li><li>After a knowledge base index is built, changing the embedding model may require rebuilding the index.</li><li>If you are only building a chat application, you can skip embedding configuration for now.</li></ul><h2 id="_5-select-a-model-in-your-application" tabindex="-1">5. Select a Model in Your Application <a class="header-anchor" href="#_5-select-a-model-in-your-application" aria-label="Permalink to &quot;5. Select a Model in Your Application&quot;">​</a></h2><p>Open the orchestration page of your Dify application and select the model under the Tokeness provider in the model selector.</p><p>First test:</p><ol><li>Create a new blank chat application.</li><li>Select the Tokeness model.</li><li>Enter a short question.</li><li>Check the Tokeness usage logs to confirm the request.</li></ol><p>In workflow applications, verify that every LLM node has a Tokeness model selected.</p><h2 id="_6-self-hosted-dify-notes" tabindex="-1">6. Self-Hosted Dify Notes <a class="header-anchor" href="#_6-self-hosted-dify-notes" aria-label="Permalink to &quot;6. Self-Hosted Dify Notes&quot;">​</a></h2><p>When self-hosting Dify, the Dify container must be able to reach <code>https://n.tokeness.io/v1</code>.</p><p>If validation fails:</p><table tabindex="0"><thead><tr><th>Check</th><th>Details</th></tr></thead><tbody><tr><td>Container network</td><td>Can the Dify API/worker container reach the internet?</td></tr><tr><td>Proxy</td><td>Does the server require an HTTP/HTTPS proxy?</td></tr><tr><td>Certificates</td><td>Are there self-signed certificates or a corporate gateway intercepting traffic?</td></tr><tr><td>Endpoint</td><td>Do not use an address that your browser can reach but the container cannot</td></tr></tbody></table><p>You can enter the Dify container and test the Tokeness endpoint with cURL.</p><h2 id="_7-troubleshooting" tabindex="-1">7. Troubleshooting <a class="header-anchor" href="#_7-troubleshooting" aria-label="Permalink to &quot;7. Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Action</th></tr></thead><tbody><tr><td>Credential validation failed</td><td>Check the endpoint, key, and container network</td></tr><tr><td>401 Unauthorized</td><td>The API key is wrong or has been disabled</td></tr><tr><td>404 Not Found</td><td>Set the API endpoint to <code>https://n.tokeness.io/v1</code></td></tr><tr><td>model not found</td><td>Re-copy the model name from the Tokeness model catalog</td></tr><tr><td>Model not found in the app</td><td>The model was not saved after adding, or was not selected in the app node</td></tr><tr><td>Knowledge base cannot index</td><td>Check whether the embedding model is configured correctly</td></tr><tr><td>No Tokeness logs</td><td>The current Dify application is not using a Tokeness model</td></tr></tbody></table><h2 id="external-documentation" tabindex="-1">External Documentation <a class="header-anchor" href="#external-documentation" aria-label="Permalink to &quot;External Documentation&quot;">​</a></h2><ul><li><a href="https://docs.dify.ai/en/use-dify/workspace/model-providers" target="_blank" rel="noreferrer">Dify Model Providers</a></li><li><a href="https://marketplace.dify.ai/plugin/langgenius/openai_api_compatible" target="_blank" rel="noreferrer">Dify OpenAI-API-compatible Marketplace Plugin</a></li></ul>`,43)])])}const u=t(i,[["render",d]]);export{m as __pageData,u as default};
